import 'package:flutter/material.dart';
import '../../state/profile_store.dart';
import '../../widgets/section_card.dart';
class PersonalInformationScreen extends StatelessWidget { final ProfileStore store; const PersonalInformationScreen({super.key, required this.store}); @override Widget build(BuildContext context) { final p = store.profile; return Scaffold(appBar: AppBar(title: const Text('Personal Information')), body: ListView(padding: const EdgeInsets.all(20), children: [SectionCard(title: 'Basic Information', children: [InfoRow(label: 'Name', value: p.name), InfoRow(label: 'Age', value: '${p.age}'), InfoRow(label: 'Sex', value: p.sex)]), const SizedBox(height: 12), SectionCard(title: 'Body & Goal', children: [InfoRow(label: 'Height', value: '${p.heightCm} cm'), InfoRow(label: 'Initial weight', value: '${p.startWeightKg} kg'), InfoRow(label: 'Target weight', value: '${p.targetWeightKg} kg'), InfoRow(label: 'Goal', value: p.goal)]), const SizedBox(height: 12), SectionCard(title: 'Lifestyle & Exercise', children: [InfoRow(label: 'Lifestyle', value: p.lifestyle), InfoRow(label: 'Frequency', value: '${p.exerciseFrequencyPerWeek} times per week'), InfoRow(label: 'Duration', value: '${p.exerciseDurationMinutes} min'), InfoRow(label: 'Exercise habit', value: p.exerciseHabit), InfoRow(label: 'Location', value: p.exerciseLocation)])])); } }
